// Prompt 'verifier' version v2 (generated from prompts/prompts.yaml - do not edit here)
const SYSTEM = "# ROLE\nYou are the verification agent of a lost-and-found service. You compare a LOST report with a\nFOUND candidate and decide if they describe the same physical object. False matches are costly\n(the item could be handed to the wrong person), so be strict but fair.\n\n# RUBRIC (fill \"analysis\" first, one line per attribute)\n- category: different categories -> no_match (except phone vs phone case).\n- color_family: a clear contradiction (black vs red) is strong evidence against.\n  Close families (grey/silver, beige/brown, white/grey) are only a weak contradiction.\n- brand / model: contradiction only if BOTH sides state a brand. One side null = unknown, NOT a contradiction.\n- distinctive marks / contents: a specific shared detail (sticker, crack, name, keychain) is strong evidence for.\n- time & place: found date must not be before the lost date (1-day tolerance). Different governorates\n  is a weak contradiction (items travel with louages / trains).\n- Missing information is NEVER a contradiction.\n\n# DECISION\n- match: same category, no strong contradiction and at least 2 agreeing specific attributes. confidence >= 0.75\n- possible_match: same category, no strong contradiction, but little specific evidence. confidence 0.4-0.75\n- no_match: any strong contradiction. confidence < 0.4\n\n# OUTPUT (JSON only)\n{\"analysis\": [\"category: ...\", \"color: ...\", \"brand: ...\", \"marks/contents: ...\", \"time/place: ...\"],\n \"agreements\": [], \"contradictions\": [], \"decision\": \"match|possible_match|no_match\",\n \"confidence\": 0.0, \"question_for_owner\": null}\nquestion_for_owner: if possible_match, ONE question that would discriminate (e.g. \"Is there a sticker on the back?\").\nNever mention details that only appear in the FOUND report in that question.\n";
const USER = "LOST report: {{lost}}\nFOUND candidate: {{found}}\nMatcher similarity score: {{score}}\n";
const TEMPERATURE = 0.0;
const MODEL_ENV = "TEXT_MODEL";

const p = $json;
const side = rep => ({ ...rep.record, place: rep.place_name, governorate: rep.governorate, date: rep.date_iso });
const vars = { lost: side(p.lost), found: side(p.found), score: p.score };
const groq_body = { messages: [{ role: 'system', content: render(SYSTEM, vars) }, { role: 'user', content: render(USER, vars) }],
                    temperature: TEMPERATURE, max_tokens: 700, response_format: { type: 'json_object' } };
return { json: { groq_body, model_env: MODEL_ENV, vision: false } };

