// Prompt 'notifier' version v2 (generated from prompts/prompts.yaml - do not edit here)
const SYSTEM = "# ROLE\nYou write short, warm notifications for Lqitha, a Tunisian lost-and-found service.\n\n# RULES\n1. owner_message: tell the owner a {{decision}} was found, where it is kept (place name only),\n   and that they must answer one verification question. Max 60 words. Language: {{language}}\n   (derja = Tunisian Arabic written in LATIN letters with 3/7/9, e.g. \"l9ina telifounek\"; ar = Arabic script).\n2. challenge_question: ONE question whose answer is the hidden detail, phrased so that the\n   question itself does NOT reveal or hint at the answer (no color, no word of the answer,\n   no yes/no question). Example: hidden detail \"lock screen shows a cat\" -> \"What picture is on the\n   lock screen?\" (never \"Is there a cat on the lock screen?\").\n3. finder_message: thank the finder, say a possible owner was identified and that contact\n   details are shared only after verification. Max 40 words, same language as the finder ({{finder_language}}).\n4. Never include phone numbers, ID numbers or the hidden detail itself in any message.\n\n# OUTPUT (JSON only)\n{\"owner_message\": \"...\", \"challenge_question\": \"...\", \"finder_message\": \"...\"}\n";
const USER = "Lost report: {{lost}}\nFound report (public part): {{found}}\nHidden detail (SECRET, never reveal): {{hidden_detail}}\n";
const TEMPERATURE = 0.3;
const MODEL_ENV = "TEXT_MODEL";

const p = $json.pair;
const vars = { lost: p.lost.record, found: { ...p.found.record, kept_at: p.found.place_name }, hidden_detail: p.hidden_detail || '(none given)',
               decision: $json.verdict.decision === 'match' ? 'very likely match' : 'possible match',
               language: p.lost.language || 'fr', finder_language: p.found.language || 'fr' };
const groq_body = { messages: [{ role: 'system', content: render(SYSTEM, vars) }, { role: 'user', content: render(USER, vars) }],
                    temperature: TEMPERATURE, max_tokens: 600, response_format: { type: 'json_object' } };
return { json: { groq_body, model_env: MODEL_ENV, vision: false } };

